) ?>" required></div><div class="col-md-6"><label for="visibility" class="form-label">Visibilitas</label><select id="visibility" name="visibility" class="form-select"><?php $visibility = old('visibility', $lesson['visibility'] ?? 'internal'); ?><option value="public" <?= $visibility === 'public' ? 'selected' : '' ?>>Public</option><option value="internal" <?= $visibility === 'internal' ? 'selected' : '' ?>>Internal</option><option value="restricted" <?= $visibility === 'restricted' ? 'selected' : '' ?>>Restricted</option></select></div><div class="col-12"><label for="content" class="form-label">Konten</label><textarea id="content" name="content" class="form-control" rows="5"><?= esc(old('content', $lesson['content'] ?? '')) ?></textarea></div><div class="col-md-6"><label for="external_url" class="form-label">URL Eksternal</label><input id="external_url" name="external_url" type="url" class="form-control" value="<?= esc(old('external_url', $lesson['external_url'] ?? '')) ?>"></div><div class="col-12"><label><input type="checkbox" name="is_required" value="1" <?= old('is_required', $lesson['is_required'] ?? 1) ? 'checked' : '' ?>> Lesson wajib</label></div><div class="col-12 text-end"><button type="submit" class="btn btn-primary-600">Simpan Lesson</button></div></div></form></div></div>
